<?php namespace backend\controllers; use backend\models\GradeElement; use backend\models\GradeElementSearch; use Yii; use yii\web\Controller; use yii\web\NotFoundHttpException; class GradeElementController extends Controller { public function actionIndex(){$searchModel=new GradeElementSearch();$dataProvider=$searchModel->search(Yii::$app->request->queryParams);return $this->render('index',compact('searchModel','dataProvider'));} public function actionCreate(){$model=new GradeElement();if($model->load(Yii::$app->request->post())&&$model->save())return $this->redirect(['view','id'=>$model->id]);return $this->render('create',compact('model'));} public function actionView($id){$model=$this->find($id);return $this->render('view',compact('model'));} public function actionUpdate($id){$model=$this->find($id);if($model->load(Yii::$app->request->post())&&$model->save())return $this->redirect(['view','id'=>$model->id]);return $this->render('update',compact('model'));} public function actionDelete($id){$this->find($id)->delete();return $this->redirect(['index']);} private function find($id){if(($m=GradeElement::findOne($id))!==null)return $m;throw new NotFoundHttpException();}}
